   figs:[{f:"vmul:14,3"},{f:"vmul:24,13",cap:"24 × 13: أضرب في 3 ثم في 10، ثم أجمع: 72 + 240 = 312"},{f:"ldiv:46,2"},{f:"ldiv:618,6",cap:"618 ÷ 6 = 103: الرقم 1 لا يقبل القسمة على 6، فأكتب 0 في الناتج."}],
